), ins as (
insert into public.mileage_value_status (vehicle_id, field, value, status, reason, source_url, evidence, run_id, old_vehicle_mileage)
select v.id, 'vehicles.mileage', x.m, x.st, x.rs, x.url, x.ev, 'mileage_status_speed_mpg_v1_20261024', v.mileage
from x join public.vehicles v on v.id=x.vid and v.mileage=x.m
on conflict do nothing returning vehicle_id, status, value, reason, run_id),
ae as (
insert into public.mileage_value_status (vehicle_id, auction_event_id, field, value, status, reason, source_url, evidence, run_id)
select ins.vehicle_id, m.auction_event_id, 'auction_event_listing_mileage', m.mileage_at_listing, 'suspect', ins.reason, m.source_url,
  'same value as suspect vehicles.mileage (method '||coalesce(m.method,'')||')', ins.run_id
from ins join public.auction_events e on e.vehicle_id=ins.vehicle_id
join public.auction_event_listing_mileage m on m.auction_event_id=e.id and m.mileage_at_listing=ins.value
where ins.status='suspect'
on conflict do nothing returning 1),
upd as (
update public.vehicles v set mileage=null from ins where ins.vehicle_id=v.id and ins.status='suspect' and v.mileage=ins.value returning 1)
select (select count(*) from ins) ins, (select count(*) from ins where status='suspect') sus, (select count(*) from ae) ae, (select count(*) from upd) upd;
